<?php	$FoundForm = 0;	$Form = GetValue(				sprintf('	SELECT cm.Nombre as Nombre, cmc.Nombre as Categoria, cm.Descripci_on as Descripci_on							FROM CelaMen_u cm								INNER JOIN CelaMen_u cmc ON ( cmc.id = cm.Categor_ia  )							WHERE cm.Referencia = %s;',					GetSQLValueString($RouteForm, 'varchar')				)			);	$Description =  GetValue(					sprintf('SELECT Acci_on FROM CelaPrivilegio WHERE Nombre = %s;',						GetSQLValueString($Action, 'varchar')					),					'Acci_on'				);	if($Form['Result'] != 'NULL') {		$CurrentGroup        = $SessionGroup;		$CurrentCategory     = mb_strtoupper($Form['Categoria'], 'utf-8');		$CurrentForm         = mb_strtoupper($Form['Nombre'], 'utf-8');		$FormCurrentAction   = mb_strtoupper($Description, 'utf-8');		$FoundForm          = 1;	}	if($FoundForm == 0){		$CurrentGroup        = $SessionGroup;		$CurrentCategory     = 'SIN CATEGOR&Iacute;A';		$CurrentForm         = mb_strtoupper(DecodeString( str_replace('.php', '', $RouteForm)), 'utf-8');		$FormCurrentAction   = 'INFORMACI&Oacute;N';		$FoundForm          = 1;	}	if($FormCurrentAction == 'NULL'){		$FormCurrentAction = mb_strtoupper(DecodeString($Action), 'utf-8');	}?><ol class="breadcrumb">	<!-- Nomnbre de la aplicación -->	<li class="breadcrumb-item">		<a href="javascript:;"> <?= mb_strtoupper($HostName, "utf-8"); ?> </a>	</li>	<!-- Rol del usuario -->	<li class="breadcrumb-item">		<a href="javascript:;"> <?= mb_strtoupper($CurrentGroup, "utf-8"); ?></a>	</li>	<!-- Categoría del formulario -->	<li class="breadcrumb-item">		<a href="javascript:;"> <?=  $CurrentCategory; ?></a>	</li>	<!-- Name del formulario  -->	<li class="breadcrumb-item">		<a href="javascript:;"> <?= $CurrentForm; ?></a>	</li>	<!-- Acción del formulario  -->	<li class="breadcrumb-item active">		<a href="javascript:;"> <?= $FormCurrentAction; ?> </a>	</li></ol><!--div class="under-header"></div--><ul class="breadcrumb" data-intro="Ruta del archivo actual" data-position="bottom" style="margin-top: -10px; margin-bottom: 10px;"></ul>